    using Structures.World;

    /// <summary>
    /// 5 creature grounds and 191 open-country packs, from the client's regions.
    ///
    /// Grounds: the regions named after the family that lives there, a pool at the region's centre
    /// (Miasma Lair miasma; Stalker Woods stalker; Warden Bot Station wardenbot; Warnet Hive warnet; Warnet Queen's Lair warnet).
    ///
    /// Open country: the regions whose own ambience, music and sky say open country, one animal
    /// pack per 15,000 m2 (at most 4) at the centre and round a ring at 55% of the radius, the
    /// family drawn by the zone's weights in creature_families.csv; never within 40 m of a friendly
    /// NPC, hospital or waypoint, 20 m of another pool's area, or inside a safe region. By zone: Abyss 14, Ashen Desert 22, Crucible 24, Howling Maw 21, Incline 9, Marshes 12, Mires 5, Palisades 20, Plains 21, Plateau 16, Pools 17, Thunderhead 10.
    ///
    /// Respawn 120 s, radius 15 m for a pack. Heights are the region marker's; the spawn point finds
    /// the ground in the column under it. region_spawns.csv has every pool with its region.
    /// </summary>
    public class RegionSpawnpoolPreloader : PreloaderBase, IPreloader
    {
        public void Preload(MigrationBuilder migrationBuilder)
        {
            Insert(migrationBuilder, SpawnPoolEntry.TableName, typeof(SpawnPoolEntry));
        }

